#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <algorithm>
using namespace std;

const int delta[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int start_node, end_node, edge_idx=1, grid_dim, max_time, INF, adjacency[1000], q_buf[1000000], edges[1000000][3], dep_map[20][20], dist_map[20][20], point_id[20][20], supply_id[20][20];
char gridA[20][20], gridB[20][20];

void add_edge(int u, int v, int capacity) {
    edges[++edge_idx][0]=v; edges[edge_idx][1]=capacity; edges[edge_idx][2]=adjacency[u]; adjacency[u]=edge_idx;
    edges[++edge_idx][0]=u; edges[edge_idx][1]=0; edges[edge_idx][2]=adjacency[v]; adjacency[v]=edge_idx;
}

void run_bfs(int x, int y, bool check) {
    int l=1, r=1, id=point_id[x][y];
    q_buf[l]=x*1000 + y;
    memset(dist_map, 63, sizeof(dist_map));
    INF=dist_map[0][0];
    dist_map[x][y]=0;
    while (l<=r) {
        int X=q_buf[l]/1000, Y=q_buf[l]%1000; l++;
        if (check && supply_id[X][Y]!=0 && dist_map[X][Y]<=max_time && dist_map[X][Y]<=dep_map[X][Y])
            add_edge(id, supply_id[X][Y], INF);
        if (dist_map[X][Y]>max_time || dist_map[X][Y]>=dep_map[X][Y]) continue;
        if (id==3 && supply_id[X][Y]==9) printf("%d\n", dist_map[X][Y]);
        for (int i=0; i<4; i++) {
            int nx=X+delta[i][0], ny=Y+delta[i][1];
            if (nx>0 && nx<=grid_dim && ny>0 && ny<=grid_dim && isdigit(gridA[nx][ny]) && dist_map[nx][ny]==INF) {
                dist_map[nx][ny]=dist_map[X][Y]+1;
                q_buf[++r]=nx*1000+ny;
            }
        }
    }
}

int flow_array[1000];

bool build_path() {
    memset(flow_array, 0, sizeof(flow_array));
    int l=1, r=1; q_buf[l]=start_node; flow_array[start_node]=1;
    while (l<=r) {
        int x=q_buf[l++]; 
        for (int i=adjacency[x]; i; i=edges[i][2]) {
            int y=edges[i][0];
            if (flow_array[y] || !edges[i][1]) continue;
            flow_array[y]=flow_array[x]+1; q_buf[++r]=y;
            if (y==end_node) return true;
        }
    }
    return false;
}

int max_flow(int x, int flow) {
    if (x==end_node) return flow;
    int rem=flow;
    for (int i=adjacency[x]; i; i=edges[i][2]) {
        int y=edges[i][0];
        if (flow_array[y]!=flow_array[x]+1 || !edges[i][1]) continue;
        int pushed=max_flow(y, min(rem, edges[i][1]));
        rem-=pushed; edges[i][1]-=pushed; edges[i^1][1]+=pushed;
        if (rem==0) return flow;
    }
    if (rem==flow) flow_array[x]=-1;
    return flow - rem;
}

int main() {
    cin >> grid_dim >> max_time;
    for (int i=1; i<=grid_dim; i++) cin >> gridA[i]+1;
    for (int i=1; i<=grid_dim; i++) cin >> gridB[i]+1;
    memset(dep_map, 63, sizeof(dep_map));
    for (int i=1; i<=grid_dim; i++)
        for (int j=1; j<=grid_dim; j++)
            if (gridA[i][j]=='Z') run_bfs(i,j,false);
    memcpy(dep_map, dist_map, sizeof(dist_map));
    int t=1;
    start_node=0; end_node=1;
    for (int i=1; i<=grid_dim; i++)
        for (int j=1; j<=grid_dim; j++) {
            if (gridA[i][j]>'0' && gridA[i][j]<='9') {
                point_id[i][j]=++t;
                add_edge(start_node, t, gridA[i][j]-'0');
            }
            if (gridB[i][j]>'0' && gridB[i][j]<='9') {
                supply_id[i][j]=++t;
                add_edge(t, end_node, gridB[i][j]-'0');
            }
        }
    for (int i=1; i<=grid_dim; i++)
        for (int j=1; j<=grid_dim; j++)
            if (point_id[i][j]) run_bfs(i,j,true);
    int total=0;
    while (build_path()) total+=max_flow(start_node, INF);
    cout << total << endl;
    return 0;
}
